class Solution {
  public PolyNode addPoly(PolyNode poly1, PolyNode poly2) {
    PolyNode dummy = new PolyNode(), tail = dummy;
    while (poly1 != null || poly2 != null) {
      int coef, power;
      if (poly2 == null || (poly1 != null && poly1.power > poly2.power)) {
        coef = poly1.coefficient;
        power = poly1.power;
        poly1 = poly1.next;
      } else if (poly1 == null || poly2.power > poly1.power) {
        coef = poly2.coefficient;
        power = poly2.power;
        poly2 = poly2.next;
      } else {
        coef = poly1.coefficient + poly2.coefficient;
        power = poly1.power;
        poly1 = poly1.next;
        poly2 = poly2.next;
      }
      if (coef != 0) tail = tail.next = new PolyNode(coef, power);
    }
    return dummy.next;
  }
}
